import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ClipboardPart = "root" | "label" | "control" | "input" | "trigger" | "indicator";

export const anatomy: Anatomy<ClipboardPart> = createAnatomy("clipboard").parts(
  "root",
  "label",
  "control",
  "input",
  "trigger",
  "indicator",
);

export const parts: Record<ClipboardPart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server. Every handler checks `defaultPrevented`
 * first, which is what makes a consumer's own handler able to veto the machine
 * (merged ahead of ours by `mergeProps`).
 *
 * The indicator renders twice — a resting glyph and a copied one — and the getter
 * takes which of the two it is dressing. Neither instance gets an id: two parts
 * sharing one would be invalid DOM, and nothing ever needs to look them up.
 */

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./clipboard.anatomy";
import { getControlId, getInputId, getLabelId, getRootId, getTriggerId } from "./clipboard.dom";
import type { ClipboardApi, ClipboardIndicatorPartProps, ClipboardSchema } from "./clipboard.types";

export function connect<T extends PropTypes>(
  service: Service<ClipboardSchema>,
  normalize: NormalizeProps<T>,
): ClipboardApi<T> {
  const { context, prop, state, send, scope } = service;

  const value = context.get("value");
  const disabled = prop("disabled");
  const stateName = state.get();
  const copied = state.matches("copied");
  // Focus is context rather than a state here — the state axis belongs to the
  // copy cycle — so the source alone is the truth of focus.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const stateAttrs = {
    "data-state": stateName,
    "data-disabled": dataAttr(disabled),
  };

  return {
    value,
    copied,
    disabled,
    focusSource,
    focusVisible,

    copy(): void {
      send({ type: "COPY.REQUEST" });
    },
    setValue(next: string): void {
      send({ type: "VALUE.SET", value: next });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "data-copied": dataAttr(copied),
      }),

    getLabelProps: (): T["label"] =>
      normalize.label({
        ...parts.label.attrs,
        ...stateAttrs,
        id: getLabelId(scope),
        // Only meaningful next to the input part: a consumer who renders no
        // input should render no label either — a `for` with no target is inert.
        for: getInputId(scope),
      }),

    getControlProps: (): T["element"] =>
      normalize.element({
        ...parts.control.attrs,
        ...stateAttrs,
        id: getControlId(scope),
      }),

    getInputProps: (): T["input"] =>
      normalize.input({
        ...parts.input.attrs,
        ...stateAttrs,
        id: getInputId(scope),
        dir: prop("dir"),
        value,
        disabled,
        // Always readonly, by decision: an editable flow composes the `input`
        // component with `api.setValue` — this part is the value's display and
        // the manual fallback, not a text field.
        readOnly: true,
        "data-readonly": "",
        "data-copied": dataAttr(copied),
        onFocus(event: FocusEvent) {
          if (event.defaultPrevented) return;
          // Select-all on focus is the structural fallback: with the whole
          // value selected, Ctrl/Cmd+C is one keystroke away — the answer for
          // the insecure-context consumer the Clipboard API refuses.
          (event.currentTarget as HTMLInputElement | null)?.select();
        },
      }),

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        ...stateAttrs,
        id: getTriggerId(scope),
        dir: prop("dir"),
        type: "button",
        // Native `disabled`, like toggle: no reason to stay focusable inert.
        disabled,
        // The accessible name never changes with the state: the state change is
        // what the live region says, the name stays the action.
        "aria-label": prop("copyLabel"),
        "data-copied": dataAttr(copied),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.BLUR" });
        },
      }),

    getIndicatorProps: (props: ClipboardIndicatorPartProps = {}): T["element"] => {
      const wanted = props.copied ?? false;
      return normalize.element({
        ...parts.indicator.attrs,
        ...stateAttrs,
        // No id: this part renders twice, and a duplicated id is invalid DOM.
        "aria-hidden": ariaAttr(true),
        hidden: wanted !== copied,
        // The variant's identity, for the sheet — not the machine's state.
        "data-copied": dataAttr(wanted),
      });
    },
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "clipboard";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "input");
}

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

export function getInputEl(scope: Scope): HTMLInputElement | null {
  return scope.getById<HTMLInputElement>(getInputId(scope));
}

/**
 * Copy a value to the clipboard with visible feedback: idle → copying →
 * copied | error → idle on a timer. There is no APG "clipboard" pattern — the
 * trigger is a plain Button — but there is a machine, because there is a timer,
 * an async operation whose late resolution must be neutralisable, and a
 * screen-reader announcement tied to a transition.
 *
 * Three decisions this file must not lose:
 *
 * 1. `writeText` fires in the effect installed on *entering* `copying`. The
 *    service runs `runTransition` synchronously from the click handler and
 *    installs a state's effects on entry, so the call stays inside the task of
 *    the user gesture — which is what preserves the transient user activation
 *    the Clipboard API requires. Never defer it through a timer or a microtask.
 *
 * 2. A click during `copying` is absorbed. The machine-level `TRIGGER.CLICK`
 *    targets `copying`; from `copying` that is `target === value` without
 *    `reenter`, which the interpreter treats as a no-op — the in-flight write
 *    continues, and no second `writeText` fires. From `copied`/`error` the same
 *    click restarts a full cycle, re-announcement included.
 *
 * 3. `navigator.clipboard.writeText` is the only programmatic path — no
 *    `execCommand("copy")` fallback, it has been deprecated since 2020. Failure
 *    is a first-class state: no clipboard (insecure context) or a rejected
 *    promise both land in `error`, announce `copyFailedText` and call
 *    `onCopyError`. The *user* fallback is structural: the readonly input part
 *    selects itself on focus, so Ctrl/Cmd+C is one keystroke away.
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { timeout } from "../../dom/raf";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getTriggerEl } from "./clipboard.dom";
import type { ClipboardSchema } from "./clipboard.types";

export const machine: Machine<ClipboardSchema> = createMachine<ClipboardSchema>({
  props({ props }) {
    return {
      disabled: false,
      // Long enough to read a checkmark, short enough that the control comes
      // back. A toast carries text and lasts longer; a glyph does not.
      copiedDuration: 2000,
      copiedText: "Copied to clipboard",
      copyFailedText: "Copy to clipboard failed",
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<string>(() => ({
        defaultValue: prop("defaultValue") ?? "",
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "clipboard value",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  // Pure and SSR-safe: the server always renders idle.
  initialState() {
    return "idle";
  },

  // For the whole life of the service, for the toggle's reason: the tracker has
  // to be running before the first Tab, or the very first focus reads wrong.
  effects: ["trackModality"],

  watch({ context, track, send }) {
    // The checkmark asserts "THIS value is in the clipboard"; a changed value
    // makes that feedback stale, and `copied`/`error` answer by leaving.
    track(
      () => [context.get("value")],
      () => send({ type: "VALUE.CHANGED" }),
    );
  },

  // Machine-level: activation is state-independent, like toggle — a click lands
  // the same way from idle, copied or error.
  on: {
    "TRIGGER.CLICK": { guard: "!isDisabled", target: "copying" },
    "COPY.REQUEST": { guard: "!isDisabled", target: "copying" },
    "VALUE.SET": { actions: ["setValue"] },
    "TRIGGER.FOCUS": { actions: ["captureFocusSource"] },
    "TRIGGER.BLUR": { actions: ["clearFocusSource"] },
  },

  states: {
    idle: {},

    copying: {
      effects: ["performCopy"],
      on: {
        "COPY.SUCCESS": { target: "copied" },
        "COPY.ERROR": { target: "error", actions: ["invokeOnCopyError"] },
      },
    },

    copied: {
      entry: ["announceCopied", "invokeCopiedTrue"],
      exit: ["invokeCopiedFalse"],
      effects: ["waitFeedbackReturn"],
      on: {
        "FEEDBACK.ELAPSED": { target: "idle" },
        "VALUE.CHANGED": { target: "idle" },
      },
    },

    error: {
      entry: ["announceCopyFailed"],
      effects: ["waitFeedbackReturn"],
      on: {
        "FEEDBACK.ELAPSED": { target: "idle" },
        "VALUE.CHANGED": { target: "idle" },
      },
    },
  },

  implementations: {
    guards: {
      isDisabled: ({ prop }) => prop("disabled"),
    },

    actions: {
      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },
      captureFocusSource({ context, scope }) {
        // A machine driven with no page has no modality to read — the node
        // harness sends TRIGGER.FOCUS after start, and silence beats a crash.
        if (scope.getRootNode() === null) return;
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
      // Through the shared announcer, never an `aria-live` on a part: a region
      // that appears with its content is announced by nobody, and doubling the
      // announcer's regions would make every message a phantom duplicate.
      announceCopied({ prop, scope }) {
        if (scope.getRootNode() === null) return;
        getLiveAnnouncer(scope.getDoc()).announce(prop("copiedText"), "polite");
      },
      announceCopyFailed({ prop, scope }) {
        if (scope.getRootNode() === null) return;
        getLiveAnnouncer(scope.getDoc()).announce(prop("copyFailedText"), "polite");
      },
      invokeCopiedTrue({ prop }) {
        prop("onCopiedChange")?.({ copied: true });
      },
      invokeCopiedFalse({ prop }) {
        prop("onCopiedChange")?.({ copied: false });
      },
      invokeOnCopyError({ prop, event }) {
        if (event.type === "COPY.ERROR") prop("onCopyError")?.({ error: event.error });
      },
    },

    effects: {
      trackModality({ scope }) {
        // The guard keeps `connect` with no DOM (ssr.test.ts) from ever
        // touching a document.
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      /**
       * The clock and the navigator come off the element, not off a global:
       * that is the scope rule, and it is also what makes a per-window stub
       * possible in tests. Synchronous on install — see the header.
       */
      performCopy({ context, scope, send }) {
        const win = getTriggerEl(scope)?.ownerDocument.defaultView;
        // No page means no clipboard to write — a silence, not a crash.
        if (win === null || win === undefined) return;
        // The DOM types promise `clipboard` unconditionally; an insecure
        // context does not honour that promise.
        const clipboard: Clipboard | undefined = win.navigator.clipboard;
        if (clipboard === undefined) {
          // Never a synchronous send from an effect installer: the interpreter
          // is still collecting this state's teardowns. Always a timer, even
          // at zero (the tooltip's waitOpenDelay lesson).
          return timeout(
            win,
            () =>
              send({
                type: "COPY.ERROR",
                error: new Error("navigator.clipboard is unavailable (insecure context?)"),
              }),
            0,
          );
        }
        let stale = false;
        void clipboard.writeText(context.get("value")).then(
          () => {
            if (!stale) send({ type: "COPY.SUCCESS" });
          },
          (cause: unknown) => {
            if (!stale)
              send({
                type: "COPY.ERROR",
                error: cause instanceof Error ? cause : new Error(String(cause)),
              });
          },
        );
        // A resolution arriving after `copying` was left is inert.
        return () => {
          stale = true;
        };
      },

      waitFeedbackReturn({ prop, scope, send }) {
        const win = getTriggerEl(scope)?.ownerDocument.defaultView;
        // Unit tests send FEEDBACK.ELAPSED by hand.
        if (win === null || win === undefined) return;
        return timeout(
          win,
          () => send({ type: "FEEDBACK.ELAPSED" }),
          Math.max(0, prop("copiedDuration")),
        );
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface ClipboardValueChangeDetails {
  readonly value: string;
}

export interface ClipboardCopiedChangeDetails {
  readonly copied: boolean;
}

export interface ClipboardCopyErrorDetails {
  readonly error: Error;
}

export interface ClipboardMachineProps {
  readonly dir?: Direction | undefined;
  /** Controlled: present means the consumer owns the value. */
  readonly value?: string | undefined;
  readonly defaultValue?: string | undefined;
  readonly disabled?: boolean | undefined;
  /** How long the copied/error feedback lasts before idle returns, in ms. */
  readonly copiedDuration?: number | undefined;
  /** Screen-reader announcement on success. Override to localise. */
  readonly copiedText?: string | undefined;
  /** Screen-reader announcement on failure. Override to localise. */
  readonly copyFailedText?: string | undefined;
  /** aria-label for the trigger — required in practice when it is icon-only. */
  readonly copyLabel?: string | undefined;
  readonly onValueChange?: ((details: ClipboardValueChangeDetails) => void) | undefined;
  /** Both edges: `{ copied: true }` entering `copied`, `{ copied: false }` leaving it. */
  readonly onCopiedChange?: ((details: ClipboardCopiedChangeDetails) => void) | undefined;
  readonly onCopyError?: ((details: ClipboardCopyErrorDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedClipboardMachineProps extends ClipboardMachineProps {
  readonly disabled: boolean;
  readonly copiedDuration: number;
  readonly copiedText: string;
  readonly copyFailedText: string;
}

export interface ClipboardSchema extends MachineSchema {
  /**
   * The state axis belongs to the copy cycle. Focus is context rather than a
   * state — a deliberate divergence from `toggle`: crossing focus with the
   * feedback states would multiply four states into eight for one boolean.
   */
  state: "idle" | "copying" | "copied" | "error";
  props: ResolvedClipboardMachineProps;
  /**
   * `focusSource` is the modality focus arrived under, held until focus leaves.
   * Not the modality of *now*: that one flips to pointer after 300ms of mouse
   * movement whether or not the focus moved.
   */
  context: { value: string; focusSource: InputModality | null };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "TRIGGER.FOCUS" }
    | { type: "TRIGGER.BLUR" }
    | { type: "COPY.REQUEST" }
    | { type: "COPY.SUCCESS" }
    | { type: "COPY.ERROR"; error: Error }
    | { type: "FEEDBACK.ELAPSED" }
    | { type: "VALUE.SET"; value: string }
    | { type: "VALUE.CHANGED" };
  action:
    | "setValue"
    | "captureFocusSource"
    | "clearFocusSource"
    | "announceCopied"
    | "announceCopyFailed"
    | "invokeCopiedTrue"
    | "invokeCopiedFalse"
    | "invokeOnCopyError";
  guard: "isDisabled";
  effect: "trackModality" | "performCopy" | "waitFeedbackReturn";
}

export interface ClipboardIndicatorPartProps {
  /** Which variant this element is: the copied glyph, or the resting one. */
  readonly copied?: boolean | undefined;
}

export interface ClipboardApi<T extends PropTypes = PropTypes> {
  readonly value: string;
  readonly copied: boolean;
  readonly disabled: boolean;
  /** The modality focus arrived under, or `null` while the trigger is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  copy(): void;
  setValue(value: string): void;
  getRootProps(): T["element"];
  getLabelProps(): T["label"];
  getControlProps(): T["element"];
  getInputProps(): T["input"];
  getTriggerProps(): T["button"];
  getIndicatorProps(props?: ClipboardIndicatorPartProps): T["element"];
}

export { anatomy, type ClipboardPart, parts } from "./clipboard.anatomy";
export { connect } from "./clipboard.connect";
export {
  getControlId,
  getInputEl,
  getInputId,
  getLabelId,
  getRootEl,
  getRootId,
  getTriggerEl,
  getTriggerId,
} from "./clipboard.dom";
export { machine } from "./clipboard.machine";
export type {
  ClipboardApi,
  ClipboardCopiedChangeDetails,
  ClipboardCopyErrorDetails,
  ClipboardIndicatorPartProps,
  ClipboardMachineProps,
  ClipboardSchema,
  ClipboardValueChangeDetails,
  ResolvedClipboardMachineProps,
} from "./clipboard.types";

/**
 * The clipboard in React: one machine on the root, six parts reading it.
 *
 * The indicator is the only part that takes an argument, and it is why it takes
 * one: the pair renders twice — a resting glyph and a copied one — and `copied`
 * says which of the two this element is. `connect` decides which is `hidden`, so
 * both stay mounted and the swap costs no remount.
 */

import * as clipboard from "@standarui/core/clipboard";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ClipboardApi = clipboard.ClipboardApi<ReactPropTypes>;

const ClipboardContext = createPartContext<ClipboardApi>("Clipboard");

export interface UseClipboardProps extends clipboard.ClipboardMachineProps, MachineRuntimeProps {}

export function useClipboard(props: UseClipboardProps): ClipboardApi {
  return clipboard.connect(useMachine(clipboard.machine, props), normalizeProps);
}

/** The api of the clipboard a subtree sits in — for a consumer's own chrome. */
export function useClipboardContext(): ClipboardApi {
  return ClipboardContext.usePart("ClipboardContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "disabled",
  "copiedDuration",
  "copiedText",
  "copyFailedText",
  "copyLabel",
  "onValueChange",
  "onCopiedChange",
  "onCopyError",
] as const;

export interface ClipboardRootProps
  extends UseClipboardProps,
    PartProps<"div", UseClipboardProps> {}

export function ClipboardRoot(props: ClipboardRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useClipboard(machineProps);

  return (
    <ClipboardContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ClipboardContext.Provider>
  );
}

/**
 * Only worth rendering next to the input part: its `for` names the input, and a
 * `for` with no target names nothing.
 */
export const ClipboardLabel: (props: PartProps<"label">) => ReactNode = createPart(
  ClipboardContext,
  { name: "ClipboardLabel", element: "label", props: (api) => api.getLabelProps() },
);

export const ClipboardControl: (props: PartProps<"div">) => ReactNode = createPart(
  ClipboardContext,
  { name: "ClipboardControl", element: "div", props: (api) => api.getControlProps() },
);

/**
 * Always read-only: it displays the value and it is the manual fallback — it
 * selects itself on focus, so Ctrl/Cmd+C is one keystroke away when the
 * Clipboard API refuses. An editable flow composes `<InputRoot>` with
 * `api.setValue` instead.
 */
export const ClipboardInput: (props: PartProps<"input">) => ReactNode = createPart(
  ClipboardContext,
  { name: "ClipboardInput", element: "input", props: (api) => api.getInputProps() },
);

export const ClipboardTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  ClipboardContext,
  { name: "ClipboardTrigger", element: "button", props: (api) => api.getTriggerProps() },
);

export interface ClipboardIndicatorProps
  extends clipboard.ClipboardIndicatorPartProps,
    PartProps<"span", clipboard.ClipboardIndicatorPartProps> {}

export function ClipboardIndicator(props: ClipboardIndicatorProps): ReactNode {
  const [indicatorProps, rest] = splitProps(props, ["copied"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = ClipboardContext.usePart("ClipboardIndicator");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getIndicatorProps(indicatorProps),
    elementProps,
    children,
  });
}

/**
 * `<Clipboard copyLabel="…"/>` — the field, the button beside it, and the pair of
 * glyphs that says whether the value has been taken.
 *
 * Six parts in the anatomy and five keys in `parts`; `root` is not one, for the
 * reason it never is — the root's props *are* this component's props.
 *
 * **`copyLabel` is required here and optional everywhere else, and that is the
 * exigence this layer exists to enforce.** `clipboard.connect.ts:113` writes
 * `aria-label: prop("copyLabel")` and the machine defaults it to nothing, so the
 * name is whatever the consumer passed. In the parts form that is survivable: a
 * consumer who puts the word "Copy" inside the button has named it the ordinary
 * way. This layer cannot — it fills the trigger with the indicator pair and
 * nothing else, and both indicators are `aria-hidden="true"`
 * (`clipboard.connect.ts:137`). So the composed trigger is *always* the icon-only
 * shape `clipboard.types.ts:29` calls out, and skipping the label ships a button
 * a screen reader announces as "button". `input`'s `revealLabel` is the
 * precedent; the difference is that there is no branch to make it conditional on,
 * so it is required outright rather than through a union.
 *
 * The `warn` beside it is for what the type cannot catch: `copyLabel=""` is a
 * `string` and satisfies the signature while naming nothing, and a plain-JS
 * caller has no type checker in the loop at all. `dialog`'s `closeLabel` reads
 * the empty string the same way — the difference is what follows from it. There
 * the part is dropped, because a dialog without a ✕ is still a dialog; here the
 * trigger is the component, so an unnamed one is reported and still rendered.
 *
 * The input is always placed, `date-field`'s reading: a clipboard without the
 * field is the icon-only shape the second story renders, and that is a parts-form
 * shape, the same way a `<Select>` without a portal is. It is also what
 * `ClipboardLabel` needs in order to mean anything — its `for` names the input's
 * id, and a `for` with no target names nothing — so `label` and the input cannot
 * be decided separately.
 *
 * Neither glyph is passed in. Both are drawn by `_clipboard.scss` under `:empty`
 * — the resting `doc.on.doc` and the checkmark — which is what makes this layer
 * renderable at all: before that sheet learned to draw them, `<Clipboard/>` was a
 * named button with two holes in it.
 */

import { isDev, warn } from "@standarui/core";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  ClipboardControl,
  ClipboardIndicator,
  type ClipboardIndicatorProps,
  ClipboardInput,
  ClipboardLabel,
  ClipboardRoot,
  ClipboardTrigger,
  type UseClipboardProps,
} from "./clipboard";

/** Applied last on every part, so the consumer's entry wins over the placement. */
export interface ClipboardParts {
  readonly label?: PartProps<"label"> | undefined;
  readonly control?: PartProps<"div"> | undefined;
  readonly input?: PartProps<"input"> | undefined;
  readonly trigger?: PartProps<"button"> | undefined;
  /**
   * Applied to BOTH glyphs, hence no `copied` — it identifies which of the two
   * this element is — and no `id`: the connect deliberately emits none, "this
   * part renders twice, and a duplicated id is invalid DOM"
   * (`clipboard.connect.ts:136`), so a consumer's own id would be that same
   * defect arriving from the outside. `ref` goes for the same reason as
   * pagination's cells: a single ref held by two elements holds the second.
   */
  readonly indicator?: Omit<ClipboardIndicatorProps, "copied" | "id" | "ref"> | undefined;
}

export interface ClipboardComposedProps
  extends Omit<UseClipboardProps, "copyLabel">,
    Omit<PartProps<"div", UseClipboardProps>, "children"> {
  /**
   * Names the trigger, and it is required: see the header. Content, never a
   * glyph — the sheet draws those.
   */
  readonly copyLabel: string;
  /** The field's visible label. Omitted, no label part is placed. */
  readonly label?: ReactNode;
  readonly parts?: ClipboardParts | undefined;
}

export function Clipboard(props: ClipboardComposedProps): ReactNode {
  const { label, parts, ...root } = props;

  // The half the signature cannot state: an empty string is a `string`, and a
  // caller with no type checker never met the signature at all.
  warn(
    isDev() && (root.copyLabel === undefined || root.copyLabel === ""),
    'Clipboard: `copyLabel` names the copy button and is required — the composed form fills it with two `aria-hidden` glyphs, so nothing else can name it. Pass the word, or the trigger ships as a button called "button".',
  );

  return (
    <ClipboardRoot {...root}>
      {label == null ? null : <ClipboardLabel {...parts?.label}>{label}</ClipboardLabel>}
      <ClipboardControl {...parts?.control}>
        <ClipboardInput {...parts?.input} />
        <ClipboardTrigger {...parts?.trigger}>
          <ClipboardIndicator {...parts?.indicator} />
          <ClipboardIndicator copied {...parts?.indicator} />
        </ClipboardTrigger>
      </ClipboardControl>
    </ClipboardRoot>
  );
}

